input.command:
cd /tmp && run(){ LANG=en_US.UTF-8 LC_ALL=en_US.UTF-8 /workspace/dataset/test19_executable --amount1="$1" --amount2="$2" --currency="$3" >/tmp/o4 2>/tmp/e4; rc=$?; printf '%-24s %-24s %-4s rc=%d out=[%s] err=[%s]\n' "$1" "$2" "$3" "$rc" "$(cat /tmp/o4|tr -d '\n')" "$(tail -1 /tmp/e4)"; }
echo "--- inf / nan ---"
run inf 1 USD; run 1 inf USD; run -inf 1 USD; run 1 -inf USD; run nan 1 USD; run 1 nan USD; run nan nan USD; run inf -inf USD; run Infinity 1 USD; run NaN 5 USD
